package alternate;import java.time.*;import java.util.*;public class SchoolSchedule extends Schedule implements SchoolAPI{private final int maximum;public SchoolSchedule(int maximum){this.maximum=maximum;}public List<Schedule.Lesson>forClass(String group){return forGroup(group);}public boolean withinDailyLimit(String group,LocalDate day){return forClass(group).stream().filter(l->l.date().equals(day)).count()<=maximum;}}
